def transform(grid):
    h, w = len(grid), len(grid[0])
    divider = max(set(x for row in grid for x in row),
                  key=lambda color: sum(v == color for row in grid for v in row))

    sep_rows = [r for r in range(h) if all(v == divider for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == divider for r in range(h))]

    def spans(size, separators):
        result = []
        start = 0
        for i in separators:
            if start < i:
                result.append((start, i))
            start = i + 1
        if start < size:
            result.append((start, size))
        return result

    row_spans = spans(h, sep_rows)
    col_spans = spans(w, sep_cols)

    cells = [
        grid[r][c]
        for rs, re in row_spans for cs, ce in col_spans
        for r in range(rs, re) for c in range(cs, ce)
    ]
    background = max(set(cells), key=cells.count)

    out = []
    for rs, re in row_spans:
        row = []
        for cs, ce in col_spans:
            count = sum(grid[r][c] != background
                        for r in range(rs, re) for c in range(cs, ce))
            row.append(1 if count >= 2 else background)
        out.append(row)
    return out
